CREATE TABLE [sales].[PaymentMethods]([PaymentMethodId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_PaymentMethods_Id] DEFAULT NEWSEQUENTIALID(),[MethodCode] NVARCHAR(30) NOT NULL,[MethodName] NVARCHAR(100) NOT NULL,[RequiresReference] BIT NOT NULL CONSTRAINT [DF_PaymentMethods_Reference] DEFAULT 0,[IsActive] BIT NOT NULL CONSTRAINT [DF_PaymentMethods_Active] DEFAULT 1,[DisplayOrder] INT NOT NULL CONSTRAINT [DF_PaymentMethods_Order] DEFAULT 0,[RowVersion] ROWVERSION NOT NULL,CONSTRAINT [PK_PaymentMethods] PRIMARY KEY([PaymentMethodId]),CONSTRAINT [UQ_PaymentMethods_Code] UNIQUE([MethodCode]));
